     std::string err;
+    if (!TransactionCanBeBroadcast(it->second, err)) {
+        return util::Unexpected{WalletError{WalletErrorCode::InvalidParameter, strprintf(_("can not rebroadcast %s: %s"), txid.ToString(), err)}};
